import{_ as p,a0 as a,w as l,s,ao as d,I as r,x as t,a1 as n,A as o}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const L=JSON.parse('{"title":"在 Linux 中怎样使用cp命令合并目录树 | LCTT x X-CMD","titleTemplate":false,"description":"在 Linux 中怎样使用cp命令合并目录树 | LCTT (201407) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"在 Linux 中怎样使用cp命令合并目录树 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"在 Linux 中怎样使用cp命令合并目录树 | LCTT (201407) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201407/20140724 How to Merge Directory Trees in Linux using cp Command","title":"在 Linux 中怎样使用cp命令合并目录树","tag":"201407","desc":""},"relativePath":"201407/20140724 How to Merge Directory Trees in Linux using cp Command.md","filePath":"[post].md"}'),m={name:"201407/20140724 How to Merge Directory Trees in Linux using cp Command.md"};function u(c,e,g,x,h,_){const i=a("Link");return l(),s("div",null,[e[13]||(e[13]=d('<h1 id="在-linux-中怎样使用cp命令合并目录树" tabindex="-1">在 Linux 中怎样使用cp命令合并目录树 <a class="header-anchor" href="#在-linux-中怎样使用cp命令合并目录树" aria-label="Permalink to “在 Linux 中怎样使用cp命令合并目录树”">​</a></h1><p>怎样将两个布局相似的目录树合并成一个新的目录树？为理解该问题让我们思考下面的例子.</p><p>假设 dir1 和 dir2 目录中分别有3个子目录a,b和c.目录布局如下所示:</p><p><img src="http://linoxide.com/wp-content/uploads/2014/07/01.merge_dir_layout.png" alt="Layout of input directories"> 输入目录布局</p><p>在目录a,b和c中有一些文件，tree命令的输出将能更好的说明:</p><p><img src="http://linoxide.com/wp-content/uploads/2014/07/02.merge_file_layout.png" alt="Layout of files"> 文件布局</p><h3 id="_1-使用cp命令创建合并" tabindex="-1">1. 使用cp命令创建合并: <a class="header-anchor" href="#_1-使用cp命令创建合并" aria-label="Permalink to “1. 使用cp命令创建合并:”">​</a></h3><p>现在我们将这两个目录合并成一个名为&quot;merged&quot;新的目录中.完成上述操作最简单的方式就是递归复制目录，如下图所示:</p><p><img src="http://linoxide.com/wp-content/uploads/2014/07/03.merge_cp_recursive.png" alt="Copy directories recursively to create new merge"> 递归复制完成新的合并</p><h4 id="_1-1-cp命令和替换带来的问题" tabindex="-1">1.1 cp命令和替换带来的问题: <a class="header-anchor" href="#_1-1-cp命令和替换带来的问题" aria-label="Permalink to “1.1 cp命令和替换带来的问题:”">​</a></h4><p>这种方式所带来的问题是该合并目录中所创建的文件为原文件的副本，并非原文件本身.别急, (你可能正在问自己) 如果不是原文件又有什么问题? 要回答你的问题，考虑下你有很多大文件的情况.那种情形下，复制所有的文件可能花费数小时.</p><p>现在让我们回到刚那问题上，且尝试使用mv命令而不是cp命令.</p><p><img src="http://linoxide.com/wp-content/uploads/2014/07/04.merge_mv_recursive.png" alt="Attempt to merge with mv command"> 企图使用mv命令进行合并操作</p><p>这些目录不能被合并.因此我们不能像这样使用mv命令去合并目录. 现在你该怎样将原文件保存到&quot;merged&quot;目录中?</p><h3 id="_2-解决方法" tabindex="-1">2. 解决方法: <a class="header-anchor" href="#_2-解决方法" aria-label="Permalink to “2. 解决方法:”">​</a></h3><p>cp命令有一个非常有用的选项来帮助我们摆脱这种状况. cp命令的-l 或 --link选项能够创建硬链接而非原文件副本.让我们尝试一下.</p><p>在我们尝试cp命令的硬链接选项前，让我们查看一下原文件的inode号码. 可通过tree命令--inodes选项来查看inodes:</p><p><img src="http://linoxide.com/wp-content/uploads/2014/07/05.merge_display_inodes.png" alt="Display inodes of original files"> 原文件的inodes</p><p>现在我们有了inodes的列表，对于cp命令可通过--link选项创建硬链接:</p><p><img src="http://linoxide.com/wp-content/uploads/2014/07/06.merge_create_links.png" alt="Merge directories with hard links"> 使用硬链接合并的目录</p><h4 id="_2-1-验证文件" tabindex="-1">2.1 验证文件: <a class="header-anchor" href="#_2-1-验证文件" aria-label="Permalink to “2.1 验证文件:”">​</a></h4><p>现在文件已经被复制，让我们验证一下inodes是否和原文件匹配:</p><p><img src="http://linoxide.com/wp-content/uploads/2014/07/07.merge_verify_inodes.png" alt="Verify Inodes"> Verify Inodes</p><h4 id="_2-2-清除" tabindex="-1">2.2 清除: <a class="header-anchor" href="#_2-2-清除" aria-label="Permalink to “2.2 清除:”">​</a></h4><p>正如你所看到的，这些文件的inodes和原文件的一样.现在问题已经被解决，且 原文件已被复制到合并目录中.现在我们能够移除dir1和dir2目录.</p><p><img src="http://linoxide.com/wp-content/uploads/2014/07/08.merge_cleanup.png" alt="Remove original directories"> 移除原始目录</p><hr>',27)),r("p",null,[e[1]||(e[1]=t("via: ",-1)),n(i,{href:"http://linoxide.com/linux-command/merge-directory-trees-linux/"},{default:o(()=>[...e[0]||(e[0]=[t("http://linoxide.com/linux-command/merge-directory-trees-linux/",-1)])]),_:1})]),r("p",null,[e[3]||(e[3]=t("原文作者：",-1)),n(i,{href:"http://linoxide.com/author/raghu/"},{default:o(()=>[...e[2]||(e[2]=[t("Raghu",-1)])]),_:1})]),r("p",null,[e[6]||(e[6]=t("译者：",-1)),n(i,{href:"https://github.com/hunanchenxingyu"},{default:o(()=>[...e[4]||(e[4]=[t("hunanchenxingyu",-1)])]),_:1}),e[7]||(e[7]=t(" 校对：",-1)),n(i,{href:"https://github.com/carolinewuyan"},{default:o(()=>[...e[5]||(e[5]=[t("Caroline",-1)])]),_:1})]),r("p",null,[e[10]||(e[10]=t("本文由 ",-1)),n(i,{href:"https://github.com/LCTT/TranslateProject"},{default:o(()=>[...e[8]||(e[8]=[t("LCTT",-1)])]),_:1}),e[11]||(e[11]=t(" 原创翻译，",-1)),n(i,{href:"http://linux.cn/"},{default:o(()=>[...e[9]||(e[9]=[t("Linux中国",-1)])]),_:1}),e[12]||(e[12]=t(" 荣誉推出",-1))])])}const C=p(m,[["render",u]]);export{L as __pageData,C as default};
